7	const ZIMM_DRAWER_RECIPE = 'ZimmDrawer';
8	
9	// Shared scroll-lock state — multiple ZimmDrawer instances can be open simultaneously (e.g. a
10	// nested utility drawer over a PDP drawer). Each open instance increments this counter; only
11	// the final cleanup (count back to 0) restores the original overflow value, preventing an
12	// earlier-closing drawer from unlocking the body while a second drawer is still open.
13	let scrollLockCount = 0;
14	let scrollLockPrev = '';
15	
16	// framer-motion's `Transition.ease` wants a literal, mutable 4-tuple (`BezierDefinition`) — a
17	// plain array literal infers as `number[]`, and `as const` infers a *readonly* tuple, neither of
18	// which satisfies it, hence the explicit cast.
19	const BEZIER_SLIDES_EASING = [0.87, 0, 0.13, 1] as [number, number, number, number];
20	// Mirrors theme/foundation/motion.ts's `duration.default` (300ms) and `easing.slides`
21	// (cubic-bezier(0.87, 0, 0.13, 1), "panels and overlays entering the screen") — hand-converted
22	// to framer-motion's shape (seconds, not ms; a bezier tuple, not a CSS `cubic-bezier()` string)
23	// since motion.ts's tokens are CSS-string form and framer-motion doesn't accept that form. One
24	// shared value for both enter and exit — that symmetry is the whole point (SFCC-898).
25	const DRAWER_TRANSITION = { duration: 0.3, ease: BEZIER_SLIDES_EASING };
26	
27	// `motion(chakra.div)` — framer OUTSIDE, chakra INSIDE. This ordering matters: framer's
28	// `motion()` only intercepts its own known animation props (initial/animate/exit/transition/
29	// variants) and forwards everything else straight to the wrapped component, so `transition`
30	// reaches framer-motion directly here. Chakra's OWN internal Drawer does the reverse
31	// (`chakra(Slide)`) — chakra wraps the animated component — and chakra's `shouldForwardProp`
32	// treats any prop literally named `transition` as a CSS shorthand style prop (it's a real
33	// Chakra/styled-system prop name), silently swallowing it before it ever reaches the wrapped
34	// component's real props (confirmed directly in @chakra-ui/system's should-forward-prop.js).
35	// That's why `<DrawerContent transition={...}>` had no effect and why this file no longer uses
36	// Chakra's `<DrawerContent>` at all — SFCC-898's close-animation defect (asymmetric enter/exit;
37	// Chakra's own Slide defaults to a spring-physics enter vs. a fixed 150ms tween exit, per
38	// @chakra-ui/transition's slide.js) can't be fixed through any prop that component exposes.
39	const MotionChakraDiv = motion(chakra.div);
40	
41	// Matches Figma's own named drawer sizes exactly (SFCC-898) — see zimmDrawer.css.ts's
42	// file-level comment for the width/usage table. `xLarge` has no consumer yet (Cart is a full
43	// page today, not a drawer).
44	export type ZimmDrawerSize = 'large' | 'tablet' | 'small' | 'xLarge' | 'mobile';
45	
46	type ZimmDrawerBaseProps = {
47	  /** Whether the drawer is open. */
48	  isOpen: boolean;
49	  /** Called on backdrop click, Escape, and the close button (all via Chakra's Drawer). */
50	  onClose: () => void;
51	  /** Desktop/tablet width variant — see ZimmDrawerSize. Collapses to the mobile treatment
52	   *  below the tablet breakpoint regardless of which value is chosen — see zimmDrawer.css.ts. */
53	  size: ZimmDrawerSize;
54	  children: React.ReactNode;
55	  /** Text style for the title. 'large' applies heading1 (24px, uppercase, Futura Round regular);
56	   *  'small' applies body2Strong (14px bold). Defaults to 'large'. Only relevant when `title`
57	   *  is provided. */
58	  titleStyle?: 'large' | 'small';
59	  /** Element to focus when the drawer closes. Use when the trigger may not have received
60	   *  keyboard focus before opening (e.g. mouse click) — without this Chakra falls back to
61	   *  document.body and AC10 focus-return fails. */
62	  finalFocusRef?: React.RefObject<HTMLElement>;
63	  /** Element to focus when the drawer opens. Overrides Chakra's default (first focusable element
64	   *  in the panel, usually the close button) — use to land focus directly on the primary input. */
65	  initialFocusRef?: React.RefObject<HTMLElement>;
66	};
