68	/**
69	 * Exactly one of:
70	 * - `title`       — renders an inline header row (title left, close button right); the drawer's
71	 *                   accessible name is derived from the rendered title element automatically.
72	 * - `labelledBy`  — ID of an existing element that labels the drawer (e.g. ZimmPdpDrawer's own
73	 *                   tab header). Paired with the floating close button.
74	 * - `aria-label`  — explicit string label when neither a visible title nor a separate element
75	 *                   is available.
76	 */
77	type ZimmDrawerProps = ZimmDrawerBaseProps &
78	  (
79	    | { title: string; labelledBy?: never; 'aria-label'?: never }
80	    | { title?: never; labelledBy: string; 'aria-label'?: never }
81	    | { title?: never; labelledBy?: never; 'aria-label': string }
82	  );
83	
84	// Deliberately not named `ZimmDrawerContentProps` — scripts/generateRegistry.mjs's
85	// extractTsProps merges every `*Props`-suffixed type in a file into one component's registry
86	// row when it can't isolate the preferred one (ZimmDrawerProps' multi-line union body isn't
87	// matched by its regex, which can't cross a newline — a documented limitation, not a bug to
88	// patch there). That merge was leaking this internal helper's own fields (ariaLabel,
89	// contentStyles, closeButtonStyles) into ZimmDrawer's public registry entry.
90	type ZimmDrawerContentConfig = {
91	  children: React.ReactNode;
92	  onClose: () => void;
93	  /** Renders an inline header row (title left, close button right) instead of the floating
94	   *  close button when provided — see ZimmDrawerProps' `title` member. */
95	  title?: string;
96	  titleId?: string;
97	  titleStyle?: 'large' | 'small';
98	  labelledBy?: string;
99	  ariaLabel?: string;
100	  contentStyles: SystemStyleObject;
101	  headerStyles: SystemStyleObject;
102	  headerTitleStyles: SystemStyleObject;
103	  closeButtonStyles: SystemStyleObject;
104	};
105	
106	/**
107	 * Replaces Chakra's own `<DrawerContent>` — see the `MotionChakraDiv` comment above for why.
108	 * Reuses Chakra's real dialog/focus/aria mechanics directly (`useModalContext`,
109	 * `ModalFocusScope` — both genuinely public exports, not reaching into Chakra internals) so
110	 * focus trap, initial focus, focus restore, body-scroll lock, and Escape/overlay-click-to-close
111	 * all still come from Chakra exactly as before; only the slide transition itself is now ours.
112	 *
113	 * Renders either an inline title row (title left, close button right) when `title` is passed, or
114	 * a floating close button only — see ZimmDrawer's own docblock for when each is used.
115	 *
116	 * @param props see ZimmDrawerContentConfig
117	 */
118	const ZimmDrawerContent = ({
119	  children,
120	  onClose,
121	  title,
122	  titleId,
123	  titleStyle = 'large',
124	  labelledBy,
125	  ariaLabel,
126	  contentStyles,
127	  headerStyles,
128	  headerTitleStyles,
129	  closeButtonStyles,
130	}: ZimmDrawerContentConfig) => {
131	  const { getDialogProps, getDialogContainerProps } = useModalContext();
132	  const dialogProps = getDialogProps({ 'aria-label': ariaLabel });
133	  // getDialogProps always computes `aria-labelledby` from Chakra's own <DrawerHeader> mount
134	  // state, which ZimmDrawer never renders (no header sub-component in this tree) — so it
135	  // always resolves to undefined regardless of what's passed in above. Set it directly so the
136	  // `title` and `labelledBy` prop variants of ZimmDrawerProps actually work.
137	  if (title && titleId) {
138	    dialogProps['aria-labelledby'] = titleId;
139	  } else if (labelledBy) {
140	    dialogProps['aria-labelledby'] = labelledBy;
141	  }
142	  const containerProps = getDialogContainerProps();
143	
144	  return (
145	    <ModalFocusScope>
146	      <chakra.div {...containerProps} __css={{ position: 'fixed', inset: 0, display: 'flex', zIndex: 'modal' }}>
147	        <MotionChakraDiv
148	          {...dialogProps}
149	          initial={{ x: '100%' }}
150	          animate={{ x: 0 }}
151	          exit={{ x: '100%' }}
152	          transition={DRAWER_TRANSITION}
153	          __css={{ position: 'fixed', top: 0, right: 0, bottom: 0, outline: 0, ...contentStyles }}
154	        >
155	          {title ? (
156	            <chakra.div sx={headerStyles}>
157	              <chakra.span
158	                id={titleId}
159	                sx={headerTitleStyles}
160	                textStyle={titleStyle === 'small' ? 'body2Strong' : 'heading1'}
161	              >
162	                {title}
163	              </chakra.span>
164	              <ZimmButton variant="icon" icon="close" label="Close" onClick={onClose} />
165	            </chakra.div>
166	          ) : (
167	            <chakra.div sx={closeButtonStyles}>
168	              <ZimmButton variant="icon" icon="close" label="Close" onClick={onClose} />
169	            </chakra.div>
170	          )}
171	          {/* SFCC-926 — tester reported no scrollbar when drawer content exceeds the panel
172	              height. flex:1 + minHeight:0 lets this grow into remaining space after the
173	              fixed header; overflowY:auto gives it its own independent scrollbar. */}
174	          <chakra.div __css={{ flex: 1, overflowY: 'auto', minHeight: 0 }}>
175	            {children}
176	          </chakra.div>
177	        </MotionChakraDiv>
178	      </chakra.div>
179	    </ModalFocusScope>
180	  );
181	};
182	
183	/**
184	 * Generic right-anchored slide-in drawer shell — overlay, panel, and a Figma-matched size
185	 * variant (see ZimmDrawerSize), built on Chakra's Drawer primitive (focus trap, initial focus,
186	 * focus restore, body-scroll lock, and Escape/overlay-click-to-close all come from Chakra, not
187	 * hand-rolled).
