189	 * Pass `title` to render an inline header row (title text left, close button right) sized per the
190	 * Figma drawer/header frames. Omit `title` and pass `labelledBy`/`aria-label` instead for drawers
191	 * that supply their own header (e.g. ZimmPdpDrawer's tab row), which keeps the floating close
192	 * button behaviour.
193	 *
194	 * @param props see ZimmDrawerProps
195	 */
196	export const ZimmDrawer = (props: ZimmDrawerProps) => {
197	  const { isOpen, onClose, size, children, titleStyle = 'large', finalFocusRef, initialFocusRef } = props;
198	  const styles = useMultiStyleConfig(ZIMM_DRAWER_RECIPE, { variant: size });
199	  const titleId = useId();
200	
201	  const title = 'title' in props ? props.title : undefined;
202	  const labelledBy = !title && 'labelledBy' in props ? props.labelledBy : undefined;
203	  const ariaLabel = !title && 'aria-label' in props ? props['aria-label'] : undefined;
204	
205	  // SFCC-926 — tester reported body scroll still active while any drawer is open, allowing
206	  // the page behind the overlay to scroll alongside the drawer. ZimmDrawer bypasses Chakra's
207	  // own <DrawerContent>, so blockScrollOnMount may not fire. Locking body overflow explicitly
208	  // ensures only the drawer's internal scroll area is accessible while it is open.
209	  // Uses the module-level counter so multiple open instances don't race to restore overflow.
210	  useEffect(() => {
211	    if (!isOpen) return;
212	    if (scrollLockCount === 0) {
213	      scrollLockPrev = document.body.style.overflow;
214	      document.body.style.overflow = 'hidden';
215	    }
216	    scrollLockCount++;
217	    return () => {
218	      scrollLockCount--;
219	      if (scrollLockCount === 0) {
220	        document.body.style.overflow = scrollLockPrev;
221	        scrollLockPrev = '';
222	      }
223	    };
224	  }, [isOpen]);
225	
226	  // Chakra's FocusLock remains active during the exit animation, so any focus call made
227	  // while the drawer is still mounted (rAF, close-button onClick) gets trapped and dropped.
228	  // onCloseComplete fires after the animation finishes and FocusLock is released — the only
229	  // reliable moment to restore focus. Covers both close-button click and Escape for all
230	  // consumers that pass finalFocusRef.
231	  const handleCloseComplete = () => {
232	    if (finalFocusRef) finalFocusRef.current?.focus();
233	  };
234	
235	  return (
236	    <Drawer
237	      isOpen={isOpen}
238	      onClose={onClose}
239	      placement="right"
240	      onCloseComplete={handleCloseComplete}
241	      initialFocusRef={initialFocusRef}
242	    >
243	      <DrawerOverlay sx={styles.overlay} />
244	      {/* aria-labelledby (not aria-label) for the title case: Chakra's own <DrawerContent>
245	          would clobber it with its own headingId (undefined without a DrawerHeader), but
246	          ZimmDrawerContent bypasses <DrawerContent> entirely and sets dialogProps itself
247	          (see its own comment above) — the clobbering bug this would otherwise work around
248	          doesn't apply here, so referencing the visible title node is safe and preferred. */}
249	      <ZimmDrawerContent
250	        onClose={onClose}
251	        title={title}
252	        titleId={title ? titleId : undefined}
253	        titleStyle={titleStyle}
254	        labelledBy={labelledBy}
255	        ariaLabel={ariaLabel}
256	        contentStyles={styles.content}
257	        headerStyles={styles.header}
258	        headerTitleStyles={styles.headerTitle}
259	        closeButtonStyles={styles.closeButton}
260	      >
261	        {children}
262	      </ZimmDrawerContent>
263	    </Drawer>
264	  );
265	};
