import React from 'react';
import { describe, test, expect, vi, beforeEach, afterEach } from 'vitest';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { ChakraProvider } from '@chakra-ui/react';
import { MemoryRouter, useLocation } from 'react-router-dom';
import theme from 'app/theme';
import { DrawerMenuView } from './index';
import DrawerMenu from './index';
import { useHeaderNav } from 'app/hooks/useHeaderNav';
import { useDrawerMenuState } from 'app/hooks/useDrawerMenuState';
import type { ContentfulAsset, HeaderNavItemEntry, ImageEntry, NavGroupEntry } from 'app/types/contentful';

// jsdom has no matchMedia implementation, and DrawerMenuView's Drawer sizing uses
// useBreakpointValue internally, which calls it — a per-file polyfill, not a change to the
// frozen vitest.setup.ts (Tier 1), since no other suite in this repo has exercised a Chakra
// Drawer/useBreakpointValue combination yet.
beforeEach(() => {
  Object.defineProperty(window, 'matchMedia', {
    writable: true,
    value: vi.fn().mockImplementation((query: string) => ({
      matches: false,
      media: query,
      onchange: null,
      addListener: vi.fn(),
      removeListener: vi.fn(),
      addEventListener: vi.fn(),
      removeEventListener: vi.fn(),
      dispatchEvent: vi.fn(),
    })),
  });
});

// Module-level vi.mock()s below (useHeaderNav, useDrawerMenuState) carry mockReturnValue/call
// history across tests unless cleared — per .claude/rules/testing.md.
afterEach(() => vi.clearAllMocks());

// No ZimmIcon/LocaleSelector/SocialIcons mocks needed — the mobile drawer's L1/L2 content
// (index.tsx) doesn't import any of them: the account/store-locator/locale/support/social
// sections and the chevron affordance were all trimmed to match Figma's "Expanded Menu" frame
// (plain-text L1 rows, Wishlist/Account footer only). See .claude/rules/testing.md's "Known
// gap: ZimmIcon throws under Vitest" if a future addition to this component reintroduces one.

// SFCC-926: ZimmWishlistAuthDrawer was added to DrawerMenuView after these tests were
// written. Its import chain pulls in SFCC's use-auth-modal.js (JSX in a .js file) which
// Vitest can't parse. Stub it to a passthrough so DrawerMenuView renders and the
// Wishlist ZimmNavItem child is still visible to tests that assert on the footer.
vi.mock('app/components/ui-kits/organisms/zimmWishlistAuthDrawer', () => ({
  ZimmWishlistAuthDrawer: ({
    children,
    onAuthSuccess,
  }: {
    children: React.ReactElement;
    onAuthSuccess?: () => void;
  }) => (
    <>
      {children}
      {onAuthSuccess && (
        <button data-testid="mock-auth-success" onClick={onAuthSuccess}>
          Simulate auth success
        </button>
      )}
    </>
  ),
}));

vi.mock('@salesforce/commerce-sdk-react', () => ({
  AuthHelpers: { Logout: 'logout' },
  useAuthHelper: () => ({ mutateAsync: vi.fn() }),
  useCustomerType: () => ({ isRegistered: false }),
}));

vi.mock('@salesforce/retail-react-app/app/hooks/use-navigation', () => ({
  default: () => vi.fn(),
}));

vi.mock('@salesforce/retail-react-app/app/hooks/use-multi-site', () => ({
  default: () => ({ site: { l10n: { supportedLocales: [{ id: 'en-AU' }] } }, buildUrl: (path: string) => path }),
}));

vi.mock('@salesforce/pwa-kit-runtime/utils/ssr-config', () => ({
  getConfig: () => ({ app: {} }),
}));

const directLinkItem = (id: string, label: string, href: string): HeaderNavItemEntry => ({
  sys: { id, contentType: { sys: { id: 'headerNavItem' } } },
  fields: { label, href },
});

const navGroup = (id: string, heading: string | undefined, linkLabels: string[]): NavGroupEntry => ({
  sys: { id, contentType: { sys: { id: 'navGroup' } } },
  fields: {
    internalTitle: id,
    heading: heading as never,
    links: linkLabels.map((label, i) => ({
      sys: { id: `${id}-link-${i}`, contentType: { sys: { id: 'link' } } },
      fields: { label, href: `/${label.toLowerCase()}` },
    })),
  },
});

const asset = (url: string, description: string): ContentfulAsset => ({
  sys: { id: 'asset-1' },
  fields: {
    title: 'Promo image',
    description,
    file: { url, fileName: 'promo.jpg', contentType: 'image/jpeg', details: { size: 1024 } },
  },
});

// promoImage links the reusable `image` primitive, not a raw Asset — see
// toMegaMenuItem.ts's own comment.
const imageEntry = (assetEntry: ContentfulAsset): ImageEntry => ({
  sys: { id: 'image-1', contentType: { sys: { id: 'image' } } },
  fields: { internalTitle: 'Test image', asset: assetEntry },
});

const megaMenuItem = (
  id: string,
  label: string,
  columns: NavGroupEntry[],
  twoColumnLayout?: boolean,
  promoImage?: ImageEntry,
): HeaderNavItemEntry => ({
  sys: { id, contentType: { sys: { id: 'headerNavItem' } } },
  fields: { label, columns, twoColumnLayout, promoImage },
});

const renderView = (props: Partial<React.ComponentProps<typeof DrawerMenuView>> = {}) =>
  render(
    <MemoryRouter>
      <ChakraProvider theme={theme}>
        <DrawerMenuView
          isOpen={true}
          onClose={vi.fn()}
          items={[]}
          isLoading={false}
          activeItem={null}
          isDrilledIn={false}
          onDrillInto={vi.fn()}
          {...props}
        />
      </ChakraProvider>
    </MemoryRouter>,
  );

describe('DrawerMenuView', () => {
  test('renders a loading spinner while items is undefined', () => {
    renderView({ items: undefined, isLoading: true });

    expect(document.querySelector('.chakra-spinner')).toBeInTheDocument();
  });

  test("does not wrap the L1/L2 nav content in an atomic live region — regression guard: aria-live/aria-atomic on the whole #drawer-menu-nav wrapper re-announced every link in a freshly drilled-into L2 panel on top of the correct, already-in-place focus-move announcement (this same component's own panelRef effect), which is what produced the reads-everything-at-once bug shared with the desktop nav (list-menu.tsx)", () => {
    const activeItem = megaMenuItem('clothing', 'Clothing', [navGroup('dresses', 'Dresses', ['Mini'])]);
    renderView({ items: [activeItem], activeItem, isDrilledIn: true });

    const navWrapper = document.getElementById('drawer-menu-nav');
    expect(navWrapper).not.toHaveAttribute('aria-live');
    expect(navWrapper).not.toHaveAttribute('aria-atomic');
  });

  test('scopes aria-live/aria-atomic to just the loading indicator', () => {
    renderView({ items: undefined, isLoading: true });

    const spinner = document.querySelector('.chakra-spinner');
    expect(spinner?.closest('[aria-live]')).toHaveAttribute('aria-atomic', 'true');
    expect(document.getElementById('drawer-menu-nav')).not.toHaveAttribute('aria-live');
  });

  test('renders a direct-link L1 item as an accessible link, with no drill-down affordance', () => {
    renderView({ items: [directLinkItem('immerse', 'Z.Immerse', '/immerse')] });

    expect(screen.getByRole('link', { name: 'Z.Immerse' })).toHaveAttribute('href', '/immerse');
    expect(screen.queryByTestId('icon-chevron-right')).not.toBeInTheDocument();
  });

  test('renders an item with columns as a drill-down button, no chevron affordance', async () => {
    const onDrillInto = vi.fn();
    const item = megaMenuItem('clothing', 'Clothing', [navGroup('dresses', 'Dresses', ['Mini', 'Maxi'])]);
    renderView({ items: [item], onDrillInto });

    // Figma's "Expanded Menu" frame renders every L1 row as plain text — no chevron/icon.
    expect(screen.queryByTestId('icon-chevron-right')).not.toBeInTheDocument();
    const button = screen.getByRole('button', { name: 'Clothing' });
    await userEvent.click(button);

    expect(onDrillInto).toHaveBeenCalledWith(item);
  });

  test('L2: flattens every column of the active item into one stacked list of headings + links', () => {
    const activeItem = megaMenuItem('clothing', 'Clothing', [
      navGroup('dresses', 'Dresses', ['Mini Dresses', 'Maxi Dresses']),
      navGroup('tops', undefined, ['Shirts']),
    ]);
    renderView({ items: [activeItem], activeItem, isDrilledIn: true });

    expect(screen.getByText('Dresses')).toBeInTheDocument();
    expect(screen.getByRole('link', { name: 'Mini Dresses' })).toHaveAttribute('href', '/mini dresses');
    expect(screen.getByRole('link', { name: 'Shirts' })).toBeInTheDocument();
    // Unheaded group (navGroup('tops', undefined, ...)) renders no heading text of its own.
    expect(screen.queryByText('tops')).not.toBeInTheDocument();
    // L1 root list and its Wishlist/Account footer are hidden while drilled into L2.
    // SFCC-926: Wishlist is now a button (auth-gated via ZimmWishlistAuthDrawer), not a link.
    expect(screen.queryByRole('button', { name: 'Wishlist' })).not.toBeInTheDocument();
  });

  test('L2: renders the promo image with its mapped src/alt when the active item has one', () => {
    const activeItem = megaMenuItem(
      'new',
      'New',
      [navGroup('in-season', undefined, ['Dresses'])],
      false,
      imageEntry(asset('//images.ctfassets.net/promo.jpg', 'Model wearing the new collection')),
    );
    renderView({ items: [activeItem], activeItem, isDrilledIn: true });

    const image = screen.getByRole('img', { name: 'Model wearing the new collection' });
    expect(image).toHaveAttribute('src', '//images.ctfassets.net/promo.jpg');
    expect(image).toHaveAttribute('loading', 'lazy');
  });

  test('L2: renders no image element when the active item has no promoImage', () => {
    const activeItem = megaMenuItem('clothing', 'Clothing', [navGroup('dresses', 'Dresses', ['Mini Dresses'])]);
    renderView({ items: [activeItem], activeItem, isDrilledIn: true });

    expect(screen.queryByRole('img')).not.toBeInTheDocument();
  });

  test('L1: never renders a promo image, even when items in the list carry one', () => {
    const item = megaMenuItem(
      'new',
      'New',
      [navGroup('in-season', undefined, ['Dresses'])],
      false,
      imageEntry(asset('//images.ctfassets.net/promo.jpg', 'Model wearing the new collection')),
    );
    renderView({ items: [item], isDrilledIn: false });

    expect(screen.queryByRole('img')).not.toBeInTheDocument();
  });

  test("L2: styles each group's first link as a heading only when twoColumnLayout is set", () => {
    const activeItem = megaMenuItem(
      'collections',
      'Collections',
      [
        navGroup('rtw', undefined, ['Ready to Wear', 'The New Denim']),
        navGroup('swim', undefined, ['Swim & Resort', 'The New Wave']),
      ],
      true,
    );
    renderView({ items: [activeItem], activeItem, isDrilledIn: true });

    // heading1Strong (24px) for the primary link, heading3 (16px) for every other leaf link —
    // see L2_PRIMARY_LINK_SX/L2_LEAF_LINK_SX in index.tsx.
    expect(window.getComputedStyle(screen.getByRole('link', { name: 'Ready to Wear' })).fontSize).toBe('1.5rem');
    expect(window.getComputedStyle(screen.getByRole('link', { name: 'The New Denim' })).fontSize).toBe('1rem');
    expect(window.getComputedStyle(screen.getByRole('link', { name: 'Swim & Resort' })).fontSize).toBe('1.5rem');
    expect(window.getComputedStyle(screen.getByRole('link', { name: 'The New Wave' })).fontSize).toBe('1rem');
  });

  test('L2: does not style the first link as a heading for a single-column item', () => {
    const activeItem = megaMenuItem('clothing', 'Clothing', [navGroup('dresses', undefined, ['Dresses', 'Tops'])]);
    renderView({ items: [activeItem], activeItem, isDrilledIn: true });

    expect(window.getComputedStyle(screen.getByRole('link', { name: 'Dresses' })).fontSize).toBe('1rem');
  });

  test('returning from L2 to L1 (isDrilledIn: false) shows the root list again', () => {
    const activeItem = megaMenuItem('clothing', 'Clothing', [navGroup('dresses', 'Dresses', ['Mini'])]);
    const { rerender } = renderView({ items: [activeItem], activeItem, isDrilledIn: true });
    expect(screen.getByText('Dresses')).toBeInTheDocument();

    rerender(
      <MemoryRouter>
        <ChakraProvider theme={theme}>
          <DrawerMenuView
            isOpen={true}
            onClose={vi.fn()}
            items={[activeItem]}
            isLoading={false}
            activeItem={null}
            isDrilledIn={false}
            onDrillInto={vi.fn()}
          />
        </ChakraProvider>
      </MemoryRouter>,
    );

    expect(screen.getByRole('button', { name: 'Clothing' })).toBeInTheDocument();
    expect(screen.queryByText('Dresses')).not.toBeInTheDocument();
    // SFCC-926: Wishlist is now a button (auth-gated via ZimmWishlistAuthDrawer), not a link.
    expect(screen.getByRole('button', { name: 'Wishlist' })).toBeInTheDocument();
  });

  test('moves focus onto the L1 panel once loading finishes — regression guard: the panel is not mounted yet while isLoading/items are unsettled, so the focus effect must re-run once it actually mounts, not just on isOpen/isDrilledIn/activeItem', () => {
    const item = directLinkItem('immerse', 'Z.Immerse', '/immerse');
    const { rerender } = renderView({ items: undefined, isLoading: true });

    rerender(
      <MemoryRouter>
        <ChakraProvider theme={theme}>
          <DrawerMenuView
            isOpen={true}
            onClose={vi.fn()}
            items={[item]}
            isLoading={false}
            activeItem={null}
            isDrilledIn={false}
            onDrillInto={vi.fn()}
          />
        </ChakraProvider>
      </MemoryRouter>,
    );

    expect(document.activeElement).toContainElement(screen.getByRole('link', { name: 'Z.Immerse' }));
  });

  test('drilling from L1 into L2 moves focus onto the new panel — regression guard: L1 and L2 occupy the same subtree, so without this the L1 button that had focus unmounts and focus silently drops to document.body, restarting keyboard tab order from the top', () => {
    const activeItem = megaMenuItem('clothing', 'Clothing', [navGroup('dresses', 'Dresses', ['Mini'])]);
    const { rerender } = renderView({ items: [activeItem], activeItem: null, isDrilledIn: false });

    rerender(
      <MemoryRouter>
        <ChakraProvider theme={theme}>
          <DrawerMenuView
            isOpen={true}
            onClose={vi.fn()}
            items={[activeItem]}
            isLoading={false}
            activeItem={activeItem}
            isDrilledIn={true}
            onDrillInto={vi.fn()}
          />
        </ChakraProvider>
      </MemoryRouter>,
    );

    expect(document.activeElement).toHaveAttribute('aria-label', 'Clothing');
  });

  test('returning from L2 to L1 moves focus onto the root list panel', () => {
    const activeItem = megaMenuItem('clothing', 'Clothing', [navGroup('dresses', 'Dresses', ['Mini'])]);
    const { rerender } = renderView({ items: [activeItem], activeItem, isDrilledIn: true });

    rerender(
      <MemoryRouter>
        <ChakraProvider theme={theme}>
          <DrawerMenuView
            isOpen={true}
            onClose={vi.fn()}
            items={[activeItem]}
            isLoading={false}
            activeItem={null}
            isDrilledIn={false}
            onDrillInto={vi.fn()}
          />
        </ChakraProvider>
      </MemoryRouter>,
    );

    expect(document.activeElement).toContainElement(screen.getByRole('button', { name: 'Clothing' }));
  });

  test('guest: renders a Sign In link rather than the account accordion', () => {
    renderView();

    expect(screen.getByRole('link', { name: 'Sign In' })).toHaveAttribute('href', '/login');
  });

  test('Wishlist onAuthSuccess: closes the drawer and navigates to /account/wishlist', async () => {
    const onClose = vi.fn();
    // LocationDisplay lets us assert react-router navigation without mocking useHistory.
    const LocationDisplay = () => {
      const location = useLocation();
      return <output data-testid="location">{location.pathname}</output>;
    };

    render(
      <MemoryRouter initialEntries={['/']}>
        <ChakraProvider theme={theme}>
          <DrawerMenuView
            isOpen={true}
            onClose={onClose}
            items={[]}
            isLoading={false}
            activeItem={null}
            isDrilledIn={false}
            onDrillInto={vi.fn()}
          />
          <LocationDisplay />
        </ChakraProvider>
      </MemoryRouter>,
    );

    await userEvent.click(screen.getByTestId('mock-auth-success'));

    expect(onClose).toHaveBeenCalledOnce();
    expect(screen.getByTestId('location')).toHaveTextContent('/account/wishlist');
  });
});

// Factory mocks — see list-menu.test.tsx's identical reasoning: automocking would still
// evaluate the real modules first (pulling in their own throw-under-Vitest chains).
vi.mock('app/hooks/useHeaderNav', () => ({ useHeaderNav: vi.fn() }));
vi.mock('app/hooks/useDrawerMenuState', () => ({ useDrawerMenuState: vi.fn() }));

const mockUseHeaderNav = vi.mocked(useHeaderNav);
const mockUseDrawerMenuState = vi.mocked(useDrawerMenuState);

describe('DrawerMenu (container)', () => {
  beforeEach(() => {
    mockUseHeaderNav.mockReturnValue({
      items: [directLinkItem('immerse', 'Z.Immerse', '/immerse')],
      isLoading: false,
      isError: false,
    });
    mockUseDrawerMenuState.mockReturnValue({
      activeItem: null,
      isDrilledIn: false,
      drillInto: vi.fn(),
      notifyClosed: vi.fn(),
      registerCloseHandler: vi.fn(),
    });
  });

  test('wires useHeaderNav() and useDrawerMenuState() through to DrawerMenuView', () => {
    render(
      <MemoryRouter>
        <ChakraProvider theme={theme}>
          <DrawerMenu isOpen={true} onClose={vi.fn()} />
        </ChakraProvider>
      </MemoryRouter>,
    );

    expect(screen.getByRole('link', { name: 'Z.Immerse' })).toHaveAttribute('href', '/immerse');
  });

  test('registers its real onClose with the shared drawer state on mount, unregisters on unmount', () => {
    const registerCloseHandler = vi.fn();
    const onClose = vi.fn();
    mockUseDrawerMenuState.mockReturnValue({
      activeItem: null,
      isDrilledIn: false,
      drillInto: vi.fn(),
      notifyClosed: vi.fn(),
      registerCloseHandler,
    });

    const { unmount } = render(
      <MemoryRouter>
        <ChakraProvider theme={theme}>
          <DrawerMenu isOpen={true} onClose={onClose} />
        </ChakraProvider>
      </MemoryRouter>,
    );

    expect(registerCloseHandler).toHaveBeenCalledWith(onClose);

    unmount();
    expect(registerCloseHandler).toHaveBeenLastCalledWith(null);
  });

  test('notifies the shared drawer state closed whenever isOpen is false', () => {
    const notifyClosed = vi.fn();
    mockUseDrawerMenuState.mockReturnValue({
      activeItem: null,
      isDrilledIn: false,
      drillInto: vi.fn(),
      notifyClosed,
      registerCloseHandler: vi.fn(),
    });

    render(
      <MemoryRouter>
        <ChakraProvider theme={theme}>
          <DrawerMenu isOpen={false} onClose={vi.fn()} />
        </ChakraProvider>
      </MemoryRouter>,
    );

    expect(notifyClosed).toHaveBeenCalled();
  });
});

