    // ZimmDrawerContent's own outer container div, the dialog's direct DOM parent — not on
    // <DrawerOverlay> itself, which is purely visual (confirmed in @chakra-ui/modal/dist/
    // index.js: ModalOverlay carries no onClick at all). zimmDrawer/index.tsx's
    // ZimmDrawerContent renders `<chakra.div {...containerProps}><MotionChakraDiv
    // role="dialog" .../></chakra.div>` with no element in between, so the dialog's parent IS
    // that container. Clicking it exercises the same code path a real backdrop click does.
    const backdrop = dialog.parentElement as HTMLElement;
    await userEvent.click(backdrop);

    expect(onCloseSpy).toHaveBeenCalledTimes(1);
  });

  test('clicking the close button calls onClose', async () => {
    const onCloseSpy = vi.fn();
    await renderOpenCartDrawer(onCloseSpy);

    await userEvent.click(screen.getByRole('button', { name: /close/i }));

    expect(onCloseSpy).toHaveBeenCalledTimes(1);
  });

  test('focus returns to finalFocusRef once the drawer finishes closing', async () => {
    const onCloseSpy = vi.fn();
    const trigger = await renderOpenCartDrawer(onCloseSpy);

    await userEvent.click(screen.getByRole('button', { name: /close/i }));

    // Real framer-motion exit transition (DRAWER_TRANSITION, ~300ms — zimmDrawer/index.tsx) has
    // to finish, and FocusLock has to release, before onCloseComplete/handleCloseComplete fires
    // — give waitFor real wall-clock room for it rather than relying on its default (1000ms)
    // budget.
    await waitFor(() => expect(trigger).toHaveFocus(), { timeout: 3000 });
  });

  test('scroll position is genuinely restored on close, not merely that scroll-lock is released', async () => {
    // zimmDrawer/index.tsx's lock (module-level scrollLockCount/scrollLockPrev) only ever saves
    // and restores document.body.style.overflow — it has no window.scrollTo/scrollY logic of its
    // own. A test that only checks overflow returns to '' would pass even if some future change
    // to that mechanism reset the page's scroll position as a side effect. Pin a real, nonzero
    // scroll position independently and confirm it survives the whole open/close cycle
    // unchanged, instead of assuming "unlocked" implies "restored".
    Object.defineProperty(window, 'scrollY', { value: 850, writable: true, configurable: true });

    const onCloseSpy = vi.fn();
    await renderOpenCartDrawer(onCloseSpy);

    expect(document.body.style.overflow).toBe('hidden');
    expect(window.scrollY).toBe(850);

    await userEvent.click(screen.getByRole('button', { name: /close/i }));

    await waitFor(() => expect(document.body.style.overflow).not.toBe('hidden'));
    expect(window.scrollY).toBe(850);
  });
});

import React from 'react';
import type { Preview, Decorator } from '@storybook/react-webpack5';
import { ChakraProvider } from '@chakra-ui/react';
import { IntlProvider } from 'react-intl';
import theme from '../overrides/app/theme';
import { ZimmTokensGlobal } from '../overrides/app/theme/zimmTokensGlobal';
import { ZimmFontFace } from '../overrides/app/theme/fontFace';
import { CHAKRA_TOAST_A11Y_EXCLUDE } from './a11yExcludes';

// @salesforce/pwa-kit-runtime's browser-side getConfig() (utils/ssr-config.client.js) just
// reads window.__CONFIG__, which the real app's SSR bootstrap script sets and Storybook never
// does — every call site that reads getConfig().app (Zimmermann's own, e.g.
// overrides/app/config/contentful.ts, and base SFCC vendor code, e.g. use-auth-modal.js's and
// otp-auth/index.jsx's getConfig().app.login) throws in Storybook without this. `login: {}` is
// needed alongside `app: {}` — every other getConfig().app.* read in base SFCC guards with `?.`
// or `|| {}`, but otp-auth/index.jsx's `const {tokenLength} = getConfig().app.login` does not,
// so `.login` itself must already be an object. `sites` is needed for any story whose play
// function clicks a button that calls useNavigation() → removeSiteLocaleFromPath() →
// getConfigMatcher() → getSites(), which throws when sites is empty. Not a copy of real config
// values — just enough shape for vendor code's unguarded reads.
if (typeof window !== 'undefined') {
  (window as typeof window & { __CONFIG__?: { app: Record<string, unknown> } }).__CONFIG__ = {
    app: {
      login: {},
      sites: [
        {
          id: 'ZimmermannAU',
          alias: 'au',
          l10n: {supportedLocales: [{id: 'en-AU', alias: 'en-AU'}]},
        },
      ],
    },
  };
}

// ZimmTokensGlobal injects the --zimm-* :root custom properties, mirroring what
// _app-config does in the app. Without it, the .zimm-* global classes and the
// var(--zimm-*) component overrides (button/header/listMenu) render unresolved in
// Storybook. Same shared source as the app, so the two cannot drift.
//
// ZimmFontFace declares the self-hosted Futura Round faces, likewise mirroring
// _app-config. Without it Storybook renders the fallback stack while the app renders
// Futura Round — the fallback measures ~13% wider, so any visual comparison made in
// Storybook would not match the app or Figma. Font files are served here by the
// staticDirs mapping in .storybook/main.js.
const withChakra: Decorator = (Story) => (
  <ChakraProvider theme={theme}>
    <ZimmFontFace />
    <ZimmTokensGlobal />
    <Story />
  </ChakraProvider>
);

const withIntl: Decorator = (Story) => (
  <IntlProvider locale="en-AU" defaultLocale="en-AU">
    <Story />
  </IntlProvider>
);

const preview: Preview = {
  parameters: {
    controls: {
      matchers: {
        color: /(background|color)$/i,
        date: /date$/i,
      },
    },
    layout: 'centered',
    a11y: {
      // 'error' causes a11y violations to fail test-storybook --ci runs
      test: 'error',
      // See a11yExcludes.ts — Storybook's parameters merge is shallow, so a story that sets
      // its own parameters.a11y.context.exclude REPLACES this array rather than extending it;
      // that file's own comment documents how a story adds to it instead.
      context: {
        exclude: CHAKRA_TOAST_A11Y_EXCLUDE,
      },
    },
  },
  decorators: [withChakra, withIntl],
};

export default preview;

import React from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { ZimmDrawer } from 'app/components/ui-kits/atoms/zimmDrawer';

const ZIMM_CART_DRAWER_RECIPE = 'ZimmCartDrawer';

// SFCC-315 builds the drawer shell only — SFCC-277/272 (later commits in this same 18-commit
// plan) will replace this with the real empty-bag component. This placeholder exists only so
// the body isn't blank/broken-looking in the meantime.
const EMPTY_BAG_PLACEHOLDER_TEXT = 'Your bag is empty.';

export type ZimmCartDrawerProps = {
  /** Whether the drawer is open. */
  isOpen: boolean;
  /** Called on backdrop click, Escape, and the close button (all via ZimmDrawer/Chakra's Drawer). */
  onClose: () => void;
  /** Number of line items in the bag. Drives the header title ("BAG • {itemCount}" vs
   *  "YOUR BAG IS EMPTY") and whether `children` or the interim empty-state placeholder renders. */
  itemCount: number;
  /** Element to focus once the drawer finishes closing — see ZimmDrawer's own doc (AC10
   *  focus-return); without this Chakra falls back to focusing document.body. */
  finalFocusRef?: React.RefObject<HTMLElement>;
  /** Cart line items. This organism owns no item-rendering logic itself — the caller supplies
   *  the list (SFCC-270's ProductItem, wired in a later commit in this same plan). Rendered only
   *  while itemCount > 0. */
  children: React.ReactNode;
  /** Reserved slot for SFCC-404's message-aggregation system (validation/error/promo banners).
   *  Always rendered, even with nothing passed — see zimmCartDrawer.css.ts's `messages` part:
   *  the band reserves height regardless, so the drawer doesn't change position when a message
   *  appears or disappears. */
  messages?: React.ReactNode;
  /** Reserved slot for SFCC-275's button group (checkout / continue shopping). Not built in this
   *  commit (SFCC-315 is shell-only) — this organism only provides the slot it will render into
   *  later. */
  footer?: React.ReactNode;
};

/**
 * SFCC-315 — the Cart drawer shell. Wraps ZimmDrawer (size="xLarge") with the cart-specific
 * header title, a height-reserving messages band, a responsive items/totals layout, and a
 * footer slot.
 *
 * Deliberately not wired to a trigger yet — no `_app`/`product-view` changes, no
 * `useCartDrawer` hook, no button-group content, no real empty-state body, no message
 * aggregation. All of those are separate, later commits in this same 18-commit plan — this
 * organism is exercised only via its own Storybook stories today.
 *
 * @param props see ZimmCartDrawerProps
 */
export const ZimmCartDrawer = ({
  isOpen,
  onClose,
  itemCount,
  finalFocusRef,
  children,
  messages,
  footer,
}: ZimmCartDrawerProps) => {
  const styles = useMultiStyleConfig(ZIMM_CART_DRAWER_RECIPE, {});
  const title = itemCount === 0 ? 'YOUR BAG IS EMPTY' : `BAG • ${itemCount}`;

  return (
    <ZimmDrawer isOpen={isOpen} onClose={onClose} size="xLarge" title={title} finalFocusRef={finalFocusRef}>
      <chakra.div __css={styles.messages}>{messages}</chakra.div>
      <chakra.div __css={styles.body}>
        {itemCount === 0 ? <chakra.p textStyle="body2">{EMPTY_BAG_PLACEHOLDER_TEXT}</chakra.p> : children}
      </chakra.div>
      <chakra.div __css={styles.footer}>{footer}</chakra.div>
    </ZimmDrawer>
  );
};

import { breakpoints } from 'app/theme/foundation';

// SFCC-315 (Cart drawer): items/totals column widths for the desktop (above the desktop
// breakpoint) two-column layout, per the approved build-step spec — no --zimm-scale equivalent
// at either value yet.
// audit-allow: Figma-confirmed cart panel column widths, pending a foundation token.
const ITEMS_COLUMN_WIDTH = '22.5rem'; // 360px
const TOTALS_COLUMN_WIDTH = '26.875rem'; // 430px

// gridSystem.ts names `md` "the tablet breakpoint" (768px) and `xl` "the desktop breakpoint"
// (1280px) — reusing both aliases rather than inventing a third, per this component's own
// build-step scope note.
//
// The media-query string is inlined at each use site below (matching zimmDrawer.css.ts's own
// `[`@media (min-width: ${breakpoints.md})`]:` usage) rather than hoisted to a shared const,
// purely for readability/DRY-ness at the definition site — it makes no difference to how this
// file type-checks either way (verified via `npx tsc --noEmit`). Each part below mixes plain
// mobile-default properties with media-query-keyed overrides, so TypeScript resolves any
// bracket access into this object (e.g. `body[someMediaQueryString]`) to the union of every
// property-value shape in it, not the one specific shape that's actually there at runtime —
// see zimmCartDrawer.css.test.ts's own comment on the resulting `.toEqual(...)` workaround.

export const ZimmCartDrawer = {
  parts: ['messages', 'body', 'footer'],
  baseStyle: {
    // Reserves height even with nothing to show — designer requirement: "to prevent the cart
    // changing position depending on errors". --zimm-scale-1300 = 52px (zimmTokens.ts:168).
    messages: {
      minHeight: 'var(--zimm-scale-1300)',
      paddingInline: 'var(--zimm-scale-2xl)', // 32px — mobile/tablet page gutter
      [`@media (min-width: ${breakpoints.xl})`]: {
        paddingInline: 'var(--zimm-scale-6xl)', // 128px — desktop page gutter
      },
    },
    // Mobile default: full-width single column, 32px gutter (spacing['2xl']).
    body: {
      display: 'flex',
      flexDirection: 'column',
      width: '100%',
      paddingInline: 'var(--zimm-scale-2xl)',
      // Tablet step restated explicitly at its own breakpoint (same values as the mobile
      // default above — fluid width, NOT a computed pixel width) — see
      // .claude/rules/overrideStyling.md's "Responsive steps are explicit media queries".
      [`@media (min-width: ${breakpoints.md})`]: {
        display: 'flex',
        flexDirection: 'column',
        width: '100%',
        paddingInline: 'var(--zimm-scale-2xl)',
      },
      // Desktop: two columns (items/totals), a 140px gap between them, and a 128px page gutter
      // each side.
      [`@media (min-width: ${breakpoints.xl})`]: {
        display: 'grid',
        gridTemplateColumns: `${ITEMS_COLUMN_WIDTH} ${TOTALS_COLUMN_WIDTH}`,
        columnGap: 'var(--zimm-scale-3500)', // 140px
        paddingInline: 'var(--zimm-scale-6xl)', // 128px
      },
    },
    // No button-group content yet (SFCC-275, a later commit) — this part only carries the page
    // gutter so the slot lines up with `messages`/`body` above it once that content lands.
    footer: {
      paddingInline: 'var(--zimm-scale-2xl)',
      [`@media (min-width: ${breakpoints.xl})`]: {
        paddingInline: 'var(--zimm-scale-6xl)',
      },
    },
  },
};

